// Stand for 5 standard 1 cm spectrophotometer cuvettes
// Print orientation: base on XY plane (z = 0), pockets open upward (+Z)

// ---------------- Parameters ----------------
block_x      = 100;   // block length along X (mm)
block_y      = 28;    // block width along Y (mm)
block_h      = 25;    // block height along Z (mm)

pocket_w     = 13;    // square pocket side (mm)
pocket_depth = 22;    // pocket depth from top face (mm)
floor_t      = block_h - pocket_depth; // remaining floor under pockets (3 mm)

n_pockets    = 5;     // number of cuvette pockets
pitch        = 18;    // centre-to-centre spacing along X (mm)

eps          = 0.5;   // overshoot of cutters past the top face (mm)

$fn = 64;

// ---------------- Model ----------------
difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_x/2, -block_y/2, 0])
        cube([block_x, block_y, block_h]);

    // Row of square pockets, centred on the block
    for (i = [0 : n_pockets - 1]) {
        x_c = (i - (n_pockets - 1)/2) * pitch;
        translate([x_c - pocket_w/2, -pocket_w/2, floor_t])
            cube([pocket_w, pocket_w, pocket_depth + eps]);
    }
}
