// Horizontal pipette rest
// Print orientation: base plate on the bed, uprights building up in +Z

$fn = 96;

// ---- Base plate ----
plate_len   = 180;  // plate length along X
plate_wid   = 35;   // plate width along Y
plate_thk   = 4;    // plate thickness along Z

// ---- Uprights ----
upright_thk = 10;   // upright thickness along X
upright_h   = 40;   // upright height (from z = 0)

// ---- Cradle notch ----
notch_r     = 8;    // radius of semicircular cradle
notch_z     = upright_h; // notch centre height (on top edge)

// ---- Cutting overlap ----
eps         = 0.5;  // extension of cutting shapes past faces

module upright(x_pos) {
    difference() {
        translate([x_pos, -plate_wid/2, 0])
            cube([upright_thk, plate_wid, upright_h]);
        // semicircular cradle, axis along X, centred at y = 0, z = 40
        translate([x_pos - eps, 0, notch_z])
            rotate([0, 90, 0])
                cylinder(r = notch_r, h = upright_thk + 2*eps);
    }
}

union() {
    // base plate
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // uprights flush with each end of the plate
    for (x = [-plate_len/2, plate_len/2 - upright_thk])
        upright(x);
}
