// Flat wrench for hexagonal reagent-bottle caps
// Print orientation: plate lies flat on the bed, z = 0 to plate_t

$fn = 96;

// ---- Dimensions (mm) ----
plate_t     = 5;    // plate thickness (Z)
head_d      = 55;   // diameter of round head, centred on origin
handle_w    = 16;   // handle width (Y), centred on y = 0
handle_x0   = 0;    // handle start (X)
handle_x1   = 90;   // handle end (X)
hex_af      = 24;   // hexagon hole size across flats
eps         = 0.5;  // cut overshoot past faces

// Derived
hex_r = (hex_af / 2) / cos(30);   // hexagon circumradius (centre to vertex)

difference() {
    union() {
        // Round head
        cylinder(d = head_d, h = plate_t);
        // Straight handle
        translate([handle_x0, -handle_w / 2, 0])
            cube([handle_x1 - handle_x0, handle_w, plate_t]);
    }
    // Hexagonal hole: circle($fn=6) puts vertices on the X axis,
    // so the top and bottom flats are parallel to the X axis
    translate([0, 0, -eps])
        linear_extrude(height = plate_t + 2 * eps)
            circle(r = hex_r, $fn = 6);
}
