// Hex key organiser block
// Units: mm

// ---- Block dimensions ----
block_len    = 72;    // X length
block_wid    = 16;    // Y width
block_ht     = 25;    // Z height

// ---- Pocket parameters ----
pocket_depth = 12;    // depth of each hex pocket from top face
pitch        = 10;    // centre-to-centre spacing along X
flats        = [1.9, 2.4, 2.9, 3.4, 4.4, 5.4]; // across-flats sizes, -X to +X
n_pockets    = len(flats);

overcut      = 0.5;   // extension past the top face for clean cuts

// Circumradius of a hexagon from its across-flats size
function hex_r(af) = af / (2 * cos(30));

difference() {
    // Main block, centred in X/Y, standing on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_ht]);

    // Hexagonal pockets along y = 0, centred on the block
    // cylinder with $fn = 6 puts vertices on the X axis,
    // so two flats are parallel to the X axis.
    for (i = [0 : n_pockets - 1]) {
        x = (i - (n_pockets - 1) / 2) * pitch;
        translate([x, 0, block_ht - pocket_depth])
            cylinder(r = hex_r(flats[i]), h = pocket_depth + overcut, $fn = 6);
    }
}
