// Flat spacer ring - raises an instrument off the bench
// Units: mm. Prints flat on the bed, centred on the origin.

// ---------- Parameters ----------
ring_thickness   = 4;     // ring height (Z)
outer_diameter   = 90;    // outer diameter of annulus
inner_diameter   = 66;    // inner (bore) diameter of annulus
hole_count       = 8;     // number of through-holes
hole_diameter    = 4.5;   // through-hole diameter
hole_pcd         = 78;    // pitch circle diameter of holes
first_hole_angle = 0;     // first hole on +X axis (degrees)
cut_overlap      = 0.5;   // extra length of cutters past faces

$fn = 128;                // smoothness of ring edges
hole_fn = 64;             // smoothness of bolt holes

// ---------- Model ----------
difference() {
    // Ring body
    cylinder(h = ring_thickness, d = outer_diameter);

    // Central bore
    translate([0, 0, -cut_overlap])
        cylinder(h = ring_thickness + 2 * cut_overlap, d = inner_diameter);

    // Evenly spaced through-holes on the pitch circle
    for (i = [0 : hole_count - 1]) {
        a = first_hole_angle + i * 360 / hole_count;
        translate([hole_pcd / 2 * cos(a), hole_pcd / 2 * sin(a), -cut_overlap])
            cylinder(h = ring_thickness + 2 * cut_overlap, d = hole_diameter, $fn = hole_fn);
    }
}
