// Adjustable shim plate with two rounded-end bolt slots
$fn = 64;

// Plate dimensions
plate_len   = 80;    // plate length along X
plate_wid   = 24;    // plate width along Y
plate_thk   = 4;     // plate thickness along Z

// Slot dimensions
slot_wid    = 5.5;   // slot width (also end diameter)
slot_len    = 12;    // slot overall length, end to end
slot_x      = [-20, 20]; // slot centre X positions
slot_y      = 0;     // slot centre Y position

// Cutting overlap
eps         = 0.5;   // extension past cut faces

// Derived
slot_ctr_span = slot_len - slot_wid; // distance between end-circle centres

module slot2d() {
    hull() {
        for (s = [-1, 1])
            translate([s * slot_ctr_span / 2, 0]) circle(d = slot_wid);
    }
}

difference() {
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    for (x = slot_x)
        translate([x, slot_y, -eps])
            linear_extrude(height = plate_thk + 2 * eps)
                slot2d();
}
