// Microplate riser
// Units: mm. Print orientation: legs down on XY plane, plate on top.

// ---- Top plate ----
plate_x     = 130;   // plate length in X
plate_y     = 100;   // plate width in Y
plate_t     = 4;     // plate thickness
plate_top_z = 50;    // z of plate top face

// ---- Legs ----
leg_size    = 15;    // square leg side (X and Y)

// ---- Window ----
win_x       = 80;    // window length in X
win_y       = 50;    // window width in Y

// ---- Misc ----
eps         = 0.5;   // cutter overshoot past faces
overlap     = 0.01;  // leg/plate overlap for a clean union

// Derived
plate_bot_z = plate_top_z - plate_t;   // underside of plate (z = 46)
leg_h       = plate_bot_z;             // legs from z = 0 to plate underside

module top_plate() {
    difference() {
        translate([-plate_x/2, -plate_y/2, plate_bot_z])
            cube([plate_x, plate_y, plate_t]);
        // Central window, overshooting top and bottom faces
        translate([-win_x/2, -win_y/2, plate_bot_z - eps])
            cube([win_x, win_y, plate_t + 2*eps]);
    }
}

module legs() {
    for (sx = [-1, 1], sy = [-1, 1]) {
        // Leg corner sits flush with plate outer edges
        x0 = (sx > 0) ? plate_x/2 - leg_size : -plate_x/2;
        y0 = (sy > 0) ? plate_y/2 - leg_size : -plate_y/2;
        translate([x0, y0, 0])
            cube([leg_size, leg_size, leg_h + overlap]);
    }
}

union() {
    top_plate();
    legs();
}
