// Magnet carrier disc for rotating sample mixer
// Print orientation: flat on bed, pockets facing up

$fn = 96;

// --- Disc ---
disc_d      = 60;    // disc outer diameter
disc_h      = 10;    // disc height (thickness)

// --- Magnet pockets ---
pocket_d    = 8.2;   // magnet pocket diameter
pocket_depth= 4;     // magnet pocket depth from top face
pocket_n    = 2;     // number of pockets
pocket_pcd  = 43.8;  // pitch circle diameter of pockets
pocket_a0   = 0;     // angle of first pocket (deg, 0 = +X axis)

// --- Shaft hole ---
shaft_d     = 6;     // motor shaft through-hole diameter

// --- Cutting overlap ---
eps         = 0.5;   // extension of cutters past faces

difference() {
    // Main disc
    cylinder(d = disc_d, h = disc_h);

    // Magnet pockets in the top face
    for (i = [0 : pocket_n - 1]) {
        a = pocket_a0 + i * 360 / pocket_n;
        translate([pocket_pcd / 2 * cos(a), pocket_pcd / 2 * sin(a),
                   disc_h - pocket_depth])
            cylinder(d = pocket_d, h = pocket_depth + eps);
    }

    // Central shaft through-hole
    translate([0, 0, -eps])
        cylinder(d = shaft_d, h = disc_h + 2 * eps);
}
