// Wall mounting strip with two countersunk screw holes
// Print orientation: flat on bed, countersinks facing up (+Z)

// ---------- Parameters ----------
bar_length   = 80;    // bar length along X (mm)
bar_width    = 24;    // bar width along Y (mm)
bar_thick    = 6;     // bar thickness along Z (mm)

hole_count   = 2;     // number of screw holes
hole_spacing = 50;    // centre-to-centre spacing along X (mm)
hole_d       = 4.5;   // through-hole diameter (mm)

csk_d        = 9;     // countersink diameter at top surface (mm)
csk_angle    = 90;    // countersink included angle (degrees)
csk_depth    = (csk_d - hole_d) / 2 / tan(csk_angle / 2); // cone depth (mm) = 2.25

eps          = 0.5;   // overshoot for clean boolean cuts (mm)
$fn          = 96;    // curve resolution

// ---------- Model ----------
difference() {
    // Flat bar, centred in X/Y, resting on z = 0
    translate([-bar_length / 2, -bar_width / 2, 0])
        cube([bar_length, bar_width, bar_thick]);

    for (i = [0 : hole_count - 1]) {
        x = (i - (hole_count - 1) / 2) * hole_spacing;

        // Through-hole
        translate([x, 0, -eps])
            cylinder(h = bar_thick + 2 * eps, d = hole_d);

        // Countersink cone, extended eps above the top face at the same angle
        translate([x, 0, bar_thick - csk_depth])
            cylinder(h  = csk_depth + eps,
                     d1 = hole_d,
                     d2 = csk_d + 2 * eps * tan(csk_angle / 2));
    }
}
