// Divider insert for sample storage box: open lattice, no floor
// Print orientation: standing on bed, open top and bottom

// ---- Dimensions (mm) ----
outer_x   = 122;   // outer wall size along X
outer_y   = 62;    // outer wall size along Y
height    = 25;    // overall height
wall      = 2;     // thickness of all walls (outer and inner)
cells_x   = 6;     // number of cells along X
cells_y   = 3;     // number of cells along Y
cell      = 18;    // inside size of each square cell
eps       = 0.5;   // overcut past faces for clean differences

// Check: 6*18 + 7*2 = 122 ; 3*18 + 4*2 = 62

// Cell pitch (centre-to-centre)
pitch = cell + wall;

difference() {
    // Solid block of the full outline
    translate([-outer_x/2, -outer_y/2, 0])
        cube([outer_x, outer_y, height]);

    // Cut out every cell, through the full height (no floor)
    for (i = [0 : cells_x - 1])
        for (j = [0 : cells_y - 1])
            translate([-outer_x/2 + wall + i*pitch,
                       -outer_y/2 + wall + j*pitch,
                       -eps])
                cube([cell, cell, height + 2*eps]);
}
