// Tubing reel - printed lying on bottom flange
$fn = 128;

flange_d   = 70;   // flange diameter
flange_t   = 3;    // flange thickness
core_d     = 25;   // core diameter
core_h     = 20;   // core height (z = 3 to z = 23)
bore_d     = 8;    // central bore diameter
overlap    = 0.01; // small overlap for union
cut_extra  = 0.5;  // bore extends past faces

total_h = flange_t + core_h + flange_t; // 26 mm

difference() {
    union() {
        // bottom flange
        cylinder(d = flange_d, h = flange_t);
        // core
        translate([0, 0, flange_t - overlap])
            cylinder(d = core_d, h = core_h + 2 * overlap);
        // top flange
        translate([0, 0, flange_t + core_h])
            cylinder(d = flange_d, h = flange_t);
    }
    // central bore
    translate([0, 0, -cut_extra])
        cylinder(d = bore_d, h = total_h + 2 * cut_extra);
}
